from pathlib import Path

from docx import Document
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_LINE_SPACING
from docx.oxml.ns import qn
from docx.shared import Cm, Pt


OUT_PATH = Path(r"c:\Users\nazar\Desktop\SocialSphere_lab5_report_fixed.docx")


def configure_document() -> Document:
    doc = Document()
    section = doc.sections[0]
    section.top_margin = Cm(2)
    section.bottom_margin = Cm(2)
    section.left_margin = Cm(3)
    section.right_margin = Cm(1.5)

    normal = doc.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    normal.font.size = Pt(14)
    return doc


def add_paragraph(doc: Document, text: str = "", align=WD_ALIGN_PARAGRAPH.JUSTIFY, first_indent: bool = True, bold: bool = False):
    paragraph = doc.add_paragraph()
    paragraph.alignment = align
    paragraph_format = paragraph.paragraph_format
    paragraph_format.line_spacing_rule = WD_LINE_SPACING.ONE_POINT_FIVE
    if first_indent:
      paragraph_format.first_line_indent = Cm(1.25)

    run = paragraph.add_run(text)
    run.font.name = "Times New Roman"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    run.font.size = Pt(14)
    run.bold = bold
    return paragraph


def add_heading(doc: Document, text: str):
    add_paragraph(doc, text, align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=False, bold=True)


def add_center(doc: Document, text: str, bold: bool = False):
    return add_paragraph(doc, text, align=WD_ALIGN_PARAGRAPH.CENTER, first_indent=False, bold=bold)


def add_blank(doc: Document, count: int = 1):
    for _ in range(count):
        add_paragraph(doc, "", align=WD_ALIGN_PARAGRAPH.LEFT, first_indent=False)


def add_placeholder(doc: Document, title: str):
    add_blank(doc, 2)
    paragraph = add_center(doc, "[Место для скриншота]")
    paragraph.runs[0].italic = True
    add_center(doc, title)
    add_blank(doc, 1)


